import type { Status, StatusId } from '@data/types';
import type { Combatant, CombatEvent } from './types';

export const GUARD_CAP = 3;
/** Timed debuffs whose durations add up when reapplied (Bind Wound's Exposed plus a Hex = four rounds), capped here. */
export const STACKING_TURNS: ReadonlySet<StatusId> = new Set(['exposed', 'weak']);
export const STACK_TURNS_CAP = 4;

export function getStatus(c: Combatant, id: StatusId): Status | undefined {
  return c.statuses.find((s) => s.id === id);
}

export function hasStatus(c: Combatant, id: StatusId): boolean {
  return getStatus(c, id) !== undefined;
}

/** Apply or refresh a status. Guard/Ward stack hits (capped); Exposed/Weak add rounds (capped); others take the longer duration and larger magnitude. */
export function applyStatus(c: Combatant, id: StatusId, turns: number, magnitude: number, events: CombatEvent[]): void {
  const existing = getStatus(c, id);
  if (!existing) {
    c.statuses.push({ id, turns, magnitude: id === 'guard' || id === 'ward' ? Math.min(GUARD_CAP, magnitude) : magnitude });
  } else if (id === 'guard' || id === 'ward') {
    existing.magnitude = Math.min(GUARD_CAP, existing.magnitude + magnitude);
  } else if (STACKING_TURNS.has(id)) {
    existing.turns = Math.min(STACK_TURNS_CAP, existing.turns + turns);
    existing.magnitude = Math.max(existing.magnitude, magnitude);
  } else {
    existing.turns = Math.max(existing.turns, turns);
    existing.magnitude = Math.max(existing.magnitude, magnitude);
  }
  const s = getStatus(c, id)!;
  events.push({ t: 'statusApplied', side: c.side, status: id, turns: s.turns, magnitude: s.magnitude });
}

export function removeStatus(c: Combatant, id: StatusId, events: CombatEvent[]): void {
  const i = c.statuses.findIndex((s) => s.id === id);
  if (i < 0) return;
  c.statuses.splice(i, 1);
  events.push({ t: 'statusExpired', side: c.side, status: id });
}

/** Consume one stack of a per-hit block (Guard for physical, Ward for magic). Returns true if the hit was blocked. */
export function consumeBlock(c: Combatant, id: 'guard' | 'ward', events: CombatEvent[]): boolean {
  const g = getStatus(c, id);
  if (!g) return false;
  g.magnitude -= 1;
  if (g.magnitude <= 0) removeStatus(c, id, events);
  return true;
}
/** Guard: the next physical hit. */
export const consumeGuard = (c: Combatant, events: CombatEvent[]) => consumeBlock(c, 'guard', events);

/** Consume Brace if present. Returns true if the hit should be countered. */
export function consumeBrace(c: Combatant, events: CombatEvent[]): boolean {
  if (!hasStatus(c, 'brace')) return false;
  removeStatus(c, 'brace', events);
  return true;
}

/** Consume Chill if present. Returns true if the action should be skipped. */
export function consumeChill(c: Combatant, events: CombatEvent[]): boolean {
  if (!hasStatus(c, 'chill')) return false;
  removeStatus(c, 'chill', events);
  events.push({ t: 'chilled', side: c.side });
  return true;
}

/**
 * End-of-round tick: Burn deals its damage, Regen heals, then timed statuses lose a turn and
 * expire at zero. Guard and Chill are consumed by events, not time.
 */
export function tickStatuses(c: Combatant, events: CombatEvent[]): void {
  for (const dot of ['burn', 'curse'] as const) {
    const st = getStatus(c, dot);
    if (st && c.hp > 0) {
      const amount = Math.min(c.hp, st.magnitude);
      c.hp -= amount;
      events.push({ t: 'burn', side: c.side, amount, status: dot });
    }
  }
  // Regen (DECISIONS #69): a share of max HP back each round end; a curse halves it, as it halves every heal.
  const regen = getStatus(c, 'regen');
  if (regen && c.hp > 0) {
    let amount = Math.round((c.stats.maxHp * regen.magnitude) / 100);
    if (hasStatus(c, 'curse')) amount = Math.floor(amount / 2);
    amount = Math.min(c.stats.maxHp - c.hp, amount);
    if (amount > 0) { c.hp += amount; events.push({ t: 'heal', side: c.side, amount }); }
  }
  for (const s of c.statuses.slice()) {
    // Blackjack lasts the whole fight.
    if (s.id === 'guard' || s.id === 'ward' || s.id === 'chill' || s.id === 'blackjack') continue;
    s.turns -= 1;
    if (s.turns <= 0) removeStatus(c, s.id, events);
  }
}
